18	bool IsAllReduce(af::AscNode &node) {
19	  std::vector<ascir::AxisId> axes;
20	  GE_CHK_STATUS_RET(ScheduleUtils::GetLoopAxis(node, axes), "Get loop axis failed.");
21	  std::vector<ascir::SizeExpr> src_strides;
22	  std::vector<ascir::SizeExpr> dst_strides = node.outputs[0].attr.strides;
23	  GE_CHK_STATUS_RET(ScheduleUtils::GetReduceInputStrides(node, src_strides), "Get loop strides failed.");
24	  GE_ASSERT_TRUE((src_strides.size() == node.outputs[0].attr.strides.size()),
25	                 "The output dim cnt [%zu] of reduce mismatch with input dim cnt [%zu].", dst_strides.size(),
26	                 src_strides.size());
27	  GE_ASSERT_TRUE((src_strides.size() == axes.size()),
28	                 "The input dim cnt [%zu] of reduce mismatch with input dim cnt [%zu].", src_strides.size(),
29	                 axes.size());
30	  std::vector<ascir::AxisId> reduce_axes;
31	  for (size_t i = 0UL; i < src_strides.size(); ++i) {
32	    if (src_strides[i] != dst_strides[i] && dst_strides[i] == 0) {
33	      reduce_axes.push_back(axes[i]);
34	    }
35	  }
36	  return reduce_axes.size() == axes.size();
37	}
38	
39	Status ExpandDimsAtFirst(ascir::ImplGraph &owner_graph, const std::string &name, const af::Expression &size) {
40	  const auto graph_attr = af::AscGraphUtils::GetComputeGraph(owner_graph)->GetOrCreateAttrsGroup<af::AscGraphAttr>();
41	  if (graph_attr == nullptr) {
42	    GELOGE(af::FAILED, "Get or create graph attr failed for graph: %s", owner_graph.GetName().c_str());
43	    return af::FAILED;
44	  }
45	  GELOGD("before: axes = %s", ScheduleUtils::AxesToString(graph_attr->axis).c_str());
46	  const auto src_axes = graph_attr->axis;  // copy
47	  std::vector<af::AxisPtr> new_axes;
48	  std::shared_ptr<af::Axis> const_axis = af::MakeShared<af::Axis>();
49	  GE_CHECK_NOTNULL(const_axis, "create axis failed");
50	  const_axis->id = 0;
51	  const_axis->name = name;
52	  const_axis->type = af::Axis::kAxisTypeOriginal;
53	  const_axis->size = size;
54	  new_axes.push_back(std::move(const_axis));
55	  for (const auto &src_axis : src_axes) {
56	    std::shared_ptr<af::Axis> new_axis = af::MakeShared<af::Axis>();
57	    GE_CHECK_NOTNULL(new_axis, "create axis failed");
58	    new_axis->id = src_axis->id + 1;
59	    new_axis->name = src_axis->name;
60	    new_axis->type = src_axis->type;
61	    new_axis->size = src_axis->size;
62	    new_axes.push_back(std::move(new_axis));
63	  }
64	  graph_attr->axis = std::move(new_axes);
65	  GELOGD("after: axes = %s", ScheduleUtils::AxesToString(graph_attr->axis).c_str());
66	  return af::SUCCESS;
67	}
68	
69	Status ExpandDimsForAllReducePass::RunPass(af::AscGraph &graph) {
70	  std::vector<ascir::AxisId> old_axis_ids;
71	  std::vector<ascir::AxisId> new_axis_ids;
72	  for (const auto &node : graph.GetAllNodes()) {
73	    if (node->attr.api.compute_type == af::ComputeType::kComputeReduce) {
74	      if (!IsAllReduce(*node)) {
75	        continue;
76	      }
77	      GE_CHK_STATUS_RET(ExpandDimsAtFirst(graph, "axis_1d", af::ops::One), "Expand dims at first failed");
78	      old_axis_ids = node->attr.sched.axis;
79	      new_axis_ids.insert(new_axis_ids.end(), old_axis_ids.begin(), old_axis_ids.end());
80	      new_axis_ids.push_back(static_cast<int64_t>(new_axis_ids.size()));
81	      break;
82	    }
83	  }
84	  if (new_axis_ids.empty()) {
85	    return af::SUCCESS;
86	  }
87	  GELOGD("Expand dims for all reduce graph:%s", graph.GetName().c_str());
88	  for (const auto &node : graph.GetAllNodes()) {
89	    if (ScheduleUtils::IsIOBuffer(node)) {
90	      continue;
91	    }
92	    auto cur_axis_ids = node->attr.sched.axis;
93	    GE_ASSERT_TRUE(!cur_axis_ids.empty() && cur_axis_ids == old_axis_ids,
94	                   "Expand dims for all reduce failed node:%s, Axis id mismatches with reduce, cannot be modified.",
95	                   node->GetName().c_str());
96	    node->attr.sched.axis = new_axis_ids;
97	    for (const auto output_attr : node->outputs()) {
98	      output_attr->attr.axis = new_axis_ids;
99	      GE_ASSERT_TRUE(output_attr->attr.strides.size() == old_axis_ids.size(),
100	                     "Expand dims for all reduce failed node:%s, Strides mismatches with reduce, cannot be modified.",
101	                     node->GetName().c_str());
102	      GE_ASSERT_TRUE(output_attr->attr.repeats.size() == old_axis_ids.size(),
103	                     "Expand dims for all reduce failed node:%s, Repeats mismatches with reduce, cannot be modified.",
104	                     node->GetName().c_str());
105	      if (output_attr->attr.strides[0UL] == 0) {
106	        output_attr->attr.strides.insert(output_attr->attr.strides.begin(), af::ops::One);
107	      } else {
108	        output_attr->attr.strides.insert(output_attr->attr.strides.begin(),
109	                                         af::sym::Mul(output_attr->attr.repeats[0UL], output_attr->attr.strides[0UL]));
110	      }
111	      output_attr->attr.repeats.insert(output_attr->attr.repeats.begin(), af::ops::One);
112	    }
113	  }
114	  return af::SUCCESS;
115	}
116	}  // namespace optimize
