31	// 检查VF节点是否不支持Scalar输入，用于决定是否跳过scalar_broadcast优化
32	static bool IsVfNodeScalarUnsupported(const af::AscNodePtr &next_node, const af::AscNodePtr &first_brc_node) {
33	  // 判断节点是否支持VF
34	  if (!ascgen_utils::IsNodeSupportsVectorFunction(next_node)) {
35	    GELOGD("Node %s(%s) does not support VF, continue with other checks.", next_node->GetTypePtr(),
36	           next_node->GetNamePtr());
37	    return false;
38	  }
39	  // 从Broadcast链首个节点追溯源节点
40	  if (first_brc_node->GetInDataNodesSize() == 0UL) {
41	    GELOGD("First broadcast node %s(%s) has no input, skip optimization.", first_brc_node->GetTypePtr(),
42	           first_brc_node->GetNamePtr());
43	    return true;  // 无法追溯源节点，跳过优化（保守处理）
44	  }
45	  const auto &source_node = std::dynamic_pointer_cast<af::AscNode>(first_brc_node->GetInDataNodes().at(0UL));
46	  if (source_node == nullptr) {
47	    GELOGD("Source node of first broadcast %s(%s) is nullptr, skip optimization.", first_brc_node->GetTypePtr(),
48	           first_brc_node->GetNamePtr());
49	    return true;  // 源节点为空，跳过优化
50	  }
51	  // 源节点不是Scalar节点，跳过优化
52	  if (!IsOps<af::ascir_op::Scalar>(source_node)) {
53	    GELOGD("Source node %s(%s) is not Scalar, skip optimization for VF node %s(%s).", source_node->GetTypePtr(),
54	           source_node->GetNamePtr(), next_node->GetTypePtr(), next_node->GetNamePtr());
55	    return true;
56	  }
57	  // Scalar场景：检查Micro API是否支持scalar输入
58	  if (!ScheduleUtils::IsMicroApiSupportsScalarInput(next_node)) {
59	    GELOGD("VF node %s(%s) micro API does not support scalar input, skip optimization.", next_node->GetTypePtr(),
60	           next_node->GetNamePtr());
61	    return true;
62	  }
63	  return false;
64	}
65	Status ScalarBroadcastOptimizationPass::GetNodeScalarInputList(const af::NodePtr &node,
66	                                                               std::vector<bool> &is_scalar_list) {
67	  GE_ASSERT_NOTNULL(node);
68	  GE_ASSERT_NOTNULL(std::dynamic_pointer_cast<af::AscNode>(node));
69	  const auto &asc_node = std::dynamic_pointer_cast<af::AscNode>(node);
70	  is_scalar_list.resize(asc_node->GetInDataNodesSize(), false);
71	  for (size_t i = 0UL; i < is_scalar_list.size(); ++i) {
72	    is_scalar_list[i] = ascgen_utils::IsScalarInput(asc_node->inputs[i].attr.repeats);
73	  }
74	  return af::SUCCESS;
75	}
76	
77	Status ScalarBroadcastOptimizationPass::IsNextNodeSupportScalarInput(const NodeView &brc_node, bool &is_supported,
78	                                                                     const af::AscNodePtr &first_brc_node) {
79	  is_supported = false;
80	  if (!IsOps<Broadcast>(brc_node)) {
81	    return af::SUCCESS;
82	  }
83	
84	  for (const auto &out_anchor : brc_node->GetAllOutDataAnchors()) {
85	    GE_CHECK_NOTNULL(out_anchor);
86	    for (const auto &next_in_anchor : out_anchor->GetPeerInDataAnchorsPtr()) {
87	      GE_CHECK_NOTNULL(next_in_anchor);
88	      const auto &next_node = std::dynamic_pointer_cast<af::AscNode>(next_in_anchor->GetOwnerNode());
89	      GE_CHECK_NOTNULL(next_node);
90	      // step1: 判断节点是否支持VF，如果支持VF，则需要判断节点的VF接口是否支持scalar
91	      if (IsVfNodeScalarUnsupported(next_node, first_brc_node)) {
92	        return af::SUCCESS;
93	      }
94	      // step2: 若当前节点支持全部是Scalar，则继续校验其他节点
95	      if (ascgen_utils::IsNodeSupportsAllScalar(next_node)) {
96	        continue;
97	      }
98	
99	      // step3: 不支持全部是Scalar，则判断当前输入是Scalar时是否支持，若支持，则继续校验其他节点
100	      std::vector<bool> is_scalar_list;
101	      GE_ASSERT_SUCCESS(GetNodeScalarInputList(next_node, is_scalar_list));
102	      const auto idx = static_cast<size_t>(next_in_anchor->GetIdx());
103	      GE_ASSERT_TRUE(idx < is_scalar_list.size(), "Input index(%zu) of %s(%s) out of range(%zu)", idx,
104	                     next_node->GetTypePtr(), next_node->GetNamePtr(), is_scalar_list.size());
105	      is_scalar_list[idx] = true;
106	      if (ascgen_utils::IsNodeSupportsScalarInput(next_node, is_scalar_list)) {
107	        GELOGD("Node %s(%s) supports scalar input, index=%zu.", next_node->GetTypePtr(), next_node->GetNamePtr(), idx);
108	        continue;
109	      }
110	
111	      // 因为1个输入和超过2个输入场景比较简单，不需要调换输入，直接结束
112	      if (is_scalar_list.size() != static_cast<size_t>(kSupportScalarInputNum)) {
113	        return af::SUCCESS;  // 直接返回， is_supported 为 false
114	      }
115	
116	      // step4: 判断调换输入是否可以支持，若不支持，则结束
117	      if (!ascgen_utils::IsNodeSupportsScalarIfExchangeInputs(next_node, is_scalar_list)) {
118	        return af::SUCCESS;  // 直接返回， is_supported 为 false
119	      }
120	
121	      // step5: 若调换的输入已经是scalar，则不支持，结束
122	      const int32_t swap_input_index = kSecondInputIndex - static_cast<int32_t>(idx);  // 总共2个输入
123	      if (ascgen_utils::IsScalarInput(next_node->inputs[swap_input_index].attr.repeats)) {
124	        GELOGD("The input index 1 of %s[%s] is already scalar, not support swap with %d.", next_node->GetTypePtr(),
125	               next_node->GetNamePtr(), idx);
126	        return af::SUCCESS;  // 直接返回， is_supported 为 false
127	      }
128	
129	      // step6: 可以交换顺序，但又不支持全部是Scalar，则不允许输入是相同节点（即输入都是Scalar），结束。
130	      if (ScheduleUtils::HasSameInput(next_node)) {
131	        GELOGD("Node %s(%s) has same input, not support.", next_node->GetTypePtr(), next_node->GetNamePtr());
132	        return af::SUCCESS;
133	      }
134	
135	      // step7: 交换两个输入
136	      GE_ASSERT_SUCCESS(ScheduleUtils::SwapInputIndex(next_node, kFirstInputIndex, kSecondInputIndex));
137	    }
138	  }
139	  // 所有节点都支持scalar输入，才算支持
140	  is_supported = true;
141	  return af::SUCCESS;
142	}
