144	Status ScalarBroadcastOptimizationPass::RunPass(af::AscGraph &graph) {
145	  for (const auto &node : graph.GetAllNodes()) {
146	    GE_CHECK_NOTNULL(node);
147	    GELOGD("Check node : %s %s, out size: %d, in size: %d", node->GetTypePtr(), node->GetNamePtr(),
148	           node->GetOutDataNodesSize(), node->GetInDataNodesSize());
149	    if (!IsOps<Broadcast>(node) || !ScheduleUtils::IsScalarBroadcastNode(node)) {
150	      continue;
151	    }
152	    GELOGD("Find scalar Broadcast node [%s], start to check", node->GetNamePtr());
153	
154	    // Find more continuous Broadcast nodes.
155	    std::vector<af::AscNodePtr> continues_brc_nodes;
156	    if (!ScheduleUtils::FindContinuesBroadcastNode(node, continues_brc_nodes) || continues_brc_nodes.empty()) {
157	      continues_brc_nodes.clear();
158	      continue;
159	    }
160	    const auto &last_brc_node = continues_brc_nodes[continues_brc_nodes.size() - 1UL];
161	
162	    // Determine whether the next node supports scalar input ?
163	    bool is_next_node_supported_scalar = false;
164	    const auto &first_brc_node = std::dynamic_pointer_cast<af::AscNode>(node);
165	    GE_ASSERT_SUCCESS(IsNextNodeSupportScalarInput(last_brc_node, is_next_node_supported_scalar, first_brc_node));
166	    if (!is_next_node_supported_scalar) {
167	      continues_brc_nodes.clear();
168	      continue;
169	    }
170	
171	    // Relink first Broadcast input to last Broadcast input
172	    GE_CHECK_NOTNULL(node->GetInDataAnchor(0));
173	    auto pre_node_out_anchor = node->GetInDataAnchor(0)->GetPeerOutAnchor();
174	    GE_ASSERT_NOTNULL(pre_node_out_anchor);
175	    for (const auto &out_anchor : last_brc_node->GetAllOutDataAnchors()) {
176	      GE_CHECK_NOTNULL(out_anchor);
177	      for (const auto &next_in_anchor : out_anchor->GetPeerInDataAnchors()) {
178	        GE_CHECK_NOTNULL(next_in_anchor);
179	        GE_CHECK_NOTNULL(next_in_anchor->GetOwnerNode());
180	        const auto &next_node = std::dynamic_pointer_cast<af::AscNode>(next_in_anchor->GetOwnerNode());
181	        next_node->inputs[next_in_anchor->GetIdx()].attr = node->inputs[0].attr;
182	        GE_ASSERT_SUCCESS(af::GraphUtils::ReplaceEdgeSrc(out_anchor, next_in_anchor, pre_node_out_anchor));
183	      }
184	    }
185	
186	    // Remove all broadcast nodes.
187	    for (const auto &continues_brc_node : continues_brc_nodes) {
188	      GELOGD("Scalar Broadcast node [%s] can be optimized, remove it.", continues_brc_node->GetNamePtr());
189	      af::NodeUtils::UnlinkAll(*continues_brc_node);
190	      GE_CHECK_NOTNULL(continues_brc_node->GetOwnerComputeGraph());
191	      af::GraphUtils::RemoveNodeWithoutRelink(continues_brc_node->GetOwnerComputeGraph(), continues_brc_node);
192	    }
193	  }
194	  return af::SUCCESS;
195	}
196	}  // namespace optimize
